(x, y, t) => {
  const cx = 240, cy = 120;
  const w1x = Math.sin(x*0.018+t*0.25)*18+Math.cos(y*0.022-t*0.3)*12+Math.sin((x+y)*0.01+t*0.15)*8;
  const w1y = Math.cos(y*0.02-t*0.2)*18+Math.sin(x*0.016+t*0.35)*12+Math.cos((x-y)*0.012-t*0.18)*8;
  const w2x = Math.sin(w1x*0.03+w1y*0.02+t*0.4)*10+Math.cos(w1y*0.025-t*0.5)*6;
  const w2y = Math.cos(w1y*0.025-t*0.35)*10+Math.sin(w1x*0.02+t*0.45)*6;
  const sx = x+w1x+w2x, sy = y+w1y+w2y;
  const src = [
    [160+Math.sin(t*0.6)*100+Math.cos(t*1.2)*30, 80+Math.cos(t*0.4)*50+Math.sin(t*0.8)*20, 0.08, 2.0],
    [320+Math.cos(t*0.5)*100+Math.sin(t*1.1)*25, 160+Math.sin(t*0.7)*50+Math.cos(t*0.9)*20, 0.1, 1.7],
    [240+Math.sin(t*0.3+2)*140+Math.cos(t*0.6)*20, 120+Math.cos(t*0.5+1)*90+Math.sin(t)*15, 0.06, 2.3],
    [120+Math.cos(t*0.8+1)*80+Math.sin(t*1.3)*15, 180+Math.sin(t*0.6+3)*60+Math.cos(t*1.1)*15, 0.12, 1.5],
    [360+Math.sin(t*0.4+4)*90+Math.cos(t*0.7)*20, 60+Math.cos(t*0.9+2)*70+Math.sin(t*1.4)*15, 0.07, 2.6],
    [240+Math.cos(t*0.35+5)*120+Math.sin(t*0.65)*18, 200+Math.sin(t*0.55)*80+Math.cos(t*1.2)*12, 0.09, 1.9],
    [80+Math.sin(t*0.7+3)*60, 40+Math.cos(t*0.5+2)*40, 0.15, 3.1],
    [400+Math.cos(t*0.45+1)*70, 200+Math.sin(t*0.75+4)*50, 0.13, 2.8],
    [200+Math.sin(t*0.55+6)*90, 220+Math.cos(t*0.65+3)*60, 0.11, 2.2],
    [300+Math.cos(t*0.85+2)*55, 30+Math.sin(t*0.95+5)*45, 0.14, 3.4]
  ];
  let aS=0, iS=0, harm=0;
  for (const [sX,sY,f,sp] of src) {
    const d = Math.sqrt((sx-sX)**2+(sy-sY)**2);
    aS += Math.sin(d*f-t*sp);
    iS += Math.sin(d*f*0.7+t*sp*0.6+1.5);
    harm += Math.cos(d*f*0.5-t*sp*0.3+2.0);
  }
  const n=src.length, act=aS/n, inh=iS/n, har=harm/n;
  const bg1=(Math.sin(sx*0.04+sy*0.025+t*0.8)+Math.sin(sx*0.03-sy*0.04+t*1.1))/2;
  const bg2=(Math.sin(sx*0.08-sy*0.06+t*1.6)+Math.cos(sx*0.07+sy*0.09-t*1.4))/2;
  const bg3=Math.sin((sx+sy)*0.12+t*2.5)*0.3+Math.sin((sx-sy)*0.1-t*2)*0.3;
  const bg=bg1*0.5+bg2*0.3+bg3*0.2;
  const dist=Math.sqrt((sx-cx)**2+(sy-cy)**2), ang=Math.atan2(sy-cy,sx-cx);
  const spiral=(Math.sin(dist*0.05-ang*3-t*1.5)+Math.sin(dist*0.04+ang*4-t*1.2))*0.3+(Math.sin(dist*0.07+ang*2-t*2)+Math.cos(dist*0.06-ang*5+t*1.8))*0.2;
  const cell=Math.tanh((Math.sin(sx*0.15)*Math.sin(sy*0.15)+Math.sin((sx+sy)*0.1+t)*0.5+Math.sin(sx*0.25+t*0.7)*Math.cos(sy*0.2-t*0.5)*0.5)*1.5)*0.25;
  const flow=(Math.sin(sy*0.03+t*0.5)*Math.cos(sx*0.02-t*0.3)+Math.cos(sx*0.03-t*0.4)*Math.sin(sy*0.025+t*0.35))*0.1;
  const raw=act-inh*0.65+bg*0.25+spiral+har*0.15;
  const reaction=Math.tanh((raw+Math.sin(raw*3+t*0.8)*0.15)*2);
  const blend=reaction*0.6+cell*0.2+flow*0.1+Math.tanh(har*1.5)*0.1;
  const v=blend*0.5+0.5;
  const pal=[[6,14,58],[10,50,90],[18,120,125],[30,160,135],[180,190,65],[215,145,60],[195,75,85],[120,35,72],[50,18,55],[6,14,58]];
  const idx=v*(pal.length-1), i=Math.min(idx|0,pal.length-2), f=idx-i;
  const lum=0.85+Math.sin(reaction*Math.PI)*0.15;
  const edge=Math.abs(reaction)>0.75?1.12:Math.abs(reaction)>0.5?1.05:1.0;
  const depth=1+Math.sin(dist*0.02-t*0.3)*0.08;
  return [
    Math.min(255,(pal[i][0]+(pal[i+1][0]-pal[i][0])*f)*lum*edge*depth)|0,
    Math.min(255,(pal[i][1]+(pal[i+1][1]-pal[i][1])*f)*lum*edge*depth)|0,
    Math.min(255,(pal[i][2]+(pal[i+1][2]-pal[i][2])*f)*lum*edge*depth)|0
  ];
}
